import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 1440, height: 900 },
});

test.describe('Смена нусаха внутри молитвы', () => {
  test('NS-01 Меню смены нусаха — только список, активный отмечен — 1440 #6a86f7d8 @prod-safe @desktop', async ({ page }) => {
    // 1. Открыть `/prayer/mincha_ashkenaz`.
    await page.goto('/prayer/mincha_ashkenaz');
    const title = page.getByRole('heading', { level: 1, name: 'מנחה (אשכנזי)' });
    await expect(title).toBeVisible();

    // 2. Нажать стрелку у «מנחה (אשכנזי)».
    await page.getByLabel('בחירת נוסח. הנוסח המוצג: אשכנזי').click();
    const menu = page.getByRole('dialog');
    const group = menu.getByRole('radiogroup');
    await expect(group).toBeVisible();
    await expect(menu.getByRole('radio', { name: 'אשכנזי' })).toBeChecked();
    await expect(menu.getByText('✓')).toBeVisible();
    await expect(menu.getByRole('radio', { name: 'ספרדי' })).toBeVisible();
    await expect(menu.getByText('עדות המזרח', { exact: true })).toBeVisible();
    await expect(menu.getByText('בקרוב', { exact: true })).toBeVisible();

    // Маленькая карточка под стрелкой, нет текста-пояснения и баннера
    const box = (await group.boundingBox())!;
    expect(box.width).toBeLessThan(400);
    await expect(page.getByText(/הבחירה חלה|ההעדפה/)).toHaveCount(0);

    // 3. Нажать «עדות המזרח» — не выбирается, диалога нет.
    const edot = (await menu.getByText('עדות המזרח', { exact: true }).boundingBox())!;
    await page.mouse.click(edot.x + edot.width / 2, edot.y + edot.height / 2);
    await expect(title).toBeVisible();
    await expect(menu.getByRole('radio', { name: 'אשכנזי' })).toBeChecked();
    await expect(menu.getByText('להחליף את התפילה לנוסח')).toHaveCount(0);

    // 4. Кликнуть мимо меню.
    await page.mouse.click(100, 800);
    await expect(page.getByRole('dialog')).toHaveCount(0);
    await expect(page.getByRole('radio', { name: 'ספרדי' })).toHaveCount(0);
  });
});
